        if (id==0) data->length=length; // return actual number of accesses
        ret=0.0;
        break;


    case 16:
      passes=accesses/128;
      #if (ACCESS_STRIDE>0)
      passes*=8;
      passes/=ACCESS_STRIDE;
      #endif
      if (!passes) return 0;
      // increase length to the next larger multiple of inner loop length
      length+=length+passes*128;
      length-=length%(passes*128);
      /*
       * Input:  RAX: addr (pointer to the buffer)
       *         RBX: passes (number of iterations)
       *         RCX: running_threads (number of threads)
       *         RDX: id (thread ID)
       *         RSI: sync_ptr (pointer to sync buffer for cmpxchg and TSC sync)
       *         RDI: length (total number of accesses)
       * Output: RAX: stop timestamp 
       *         RBX: start timestamp
       *         RCX: scheduled start (0 if TSC sync is disabled)
       */
