/** assembler implementation of throughput measurement for gpr_mul_si
 */
static double asm_work_gpr_mul_si(unsigned long long addr, unsigned long long accesses, unsigned long long burst_length,unsigned long long call_latency,unsigned long long freq,unsigned long long running_threads,unsigned long long id, volatile void * sync_ptr,threaddata_t* data) __attribute__((noinline));
