    if (data->region==REGION_L2) VT_USER_START("L2");
    if (data->region==REGION_L3) VT_USER_START("L3");
    if (data->region==REGION_RAM) VT_USER_START("RAM");
   #endif

   length=data->length/16; // convert size in bytes into total number of accesses

